const wordPressSiteElsewhere = `-- name: WordPressSiteElsewhere :one
SELECT w.name AS workspace_name, w.slug AS workspace_slug
FROM wordpress_sites s
JOIN integrations i ON i.id = s.integration_id AND i.disconnected_at IS NULL
JOIN workspaces w ON w.id = s.workspace_id AND w.deleted_at IS NULL
WHERE lower(s.site_url) = lower($1) AND s.integration_id <> $2 AND s.site_url <> ''
LIMIT 1
`

type WordPressSiteElsewhereParams struct {
	SiteUrl       string    `json:"siteUrl"`
	IntegrationID uuid.UUID `json:"integrationId"`
}

type WordPressSiteElsewhereRow struct {
	WorkspaceName string `json:"workspaceName"`
	WorkspaceSlug string `json:"workspaceSlug"`
}

// A site connects to one workspace: another active connection of the same address.
func (q *Queries) WordPressSiteElsewhere(ctx context.Context, arg WordPressSiteElsewhereParams) (WordPressSiteElsewhereRow, error) {
	row := q.db.QueryRow(ctx, wordPressSiteElsewhere, arg.SiteUrl, arg.IntegrationID)
	var i WordPressSiteElsewhereRow
	err := row.Scan(&i.WorkspaceName, &i.WorkspaceSlug)
	return i, err
}

